function solve(matrix,vector){const a=matrix.map((r,i)=>[...r,vector[i]]);for(let c=0;c<3;c++){let pivot=c;for(let r=c+1;r<3;r++)if(Math.abs(a[r][c])>Math.abs(a[pivot][c]))pivot=r;[a[c],a[pivot]]=[a[pivot],a[c]];if(Math.abs(a[c][c])<1e-12)return null;const d=a[c][c];for(let k=c;k<4;k++)a[c][k]/=d;for(let r=0;r<3;r++)if(r!==c){const f=a[r][c];for(let k=c;k<4;k++)a[r][k]-=f*a[c][k];}}return a.map(r=>r[3]);}
function metrics(data,sr){let power=0,peak=0;const crossings=[],envelope=[],size=Math.round(sr*.01);for(let i=0;i<data.length;i++){power+=data[i]**2;peak=Math.max(peak,Math.abs(data[i]));if(i&&data[i-1]<0&&data[i]>=0)crossings.push(i-1-data[i-1]/(data[i]-data[i-1]));}for(let i=0;i+size<=data.length;i+=size){let p=0;for(let k=i;k<i+size;k++)p+=data[k]**2;envelope.push({t:(i+size/2)/sr,y:Math.sqrt(p/size)});}let best=null,run=0,longest=0;for(const x of envelope){run=x.y<.005?run+1:0;longest=Math.max(run,longest);}for(let frequency=1;frequency<=8;frequency+=.02){let s=0,c=0,ss=0,cc=0,sc=0,y=0,ys=0,yc=0,yy=0;for(const x of envelope){const sn=Math.sin(2*Math.PI*frequency*x.t),cs=Math.cos(2*Math.PI*frequency*x.t);s+=sn;c+=cs;ss+=sn*sn;cc+=cs*cs;sc+=sn*cs;y+=x.y;ys+=x.y*sn;yc+=x.y*cs;yy+=x.y*x.y;}const b=solve([[envelope.length,s,c],[s,ss,sc],[c,sc,cc]],[y,ys,yc]);if(b){const error=yy-b[0]*y-b[1]*ys-b[2]*yc;if(!best||error<best.error)best={frequency:+frequency.toFixed(2),error,relativeAmplitude:Math.hypot(b[1],b[2])/Math.max(1e-12,b[0])};}}return{frames:data.length,rms:Math.sqrt(power/data.length),peak,frequencyHz:crossings.length>1?(crossings.length-1)*sr/(crossings.at(-1)-crossings[0]):null,maxBelow005RunMs:longest*size/sr*1000,envelopeFit:best};}
