 const report={checks,fatalErrors:[],sampleRate:context.sampleRate,startedAt:new Date().toISOString(),scope:'Actual production AudioEngine start/rate/pitch/seek/scratch-release methods with actual WASM and routed captured PCM. No native/hardware, reverse/loop/StemSlip live integration, decoded-memory or vendor sonic-quality acceptance.',sourceHashes:{},budgets:{pitchRelative:.01,rateEnvelopeHz:.15,releaseMaximumBelow005Ms:20}};
