  await check('Production tempo and pitch controls retain live node and change actual routed PCM',async e=>{const adapter=engine.voices.get(0).liveKeylock,id=adapter.snapshot().groups[0].id;await engine.setRate(d,1.25);const beforeRate={at:context.currentTime,scheduledWhen:d.anchorTime,requestedRate:d.rate,audibleRate:engine.audibleRate(d)};engine.updateFXBPMs([120*engine.audibleRate(d)]);assert(context.currentTime<d.anchorTime&&engine.nodes[0].channelBpm===120,'FX prematurely used requested future rate');const rate=await measured(single,d.anchorTime+.25,1.3);tone(rate,440);engine.updateFXBPMs([120*engine.audibleRate(d)]);assert(engine.nodes[0].channelBpm===150,'FX did not adopt actual live rate');e.fxClock={beforeRate,afterBPM:engine.nodes[0].channelBpm,limitation:'Main animation-frame synchronization; no sample-accurate FX automation claim'};assert(Math.abs(rate.envelopeFit.frequency-5)<=.15,'Source modulation rate did not change');await engine.setPitch(d,{keylock:true,semitones:12});const higher=await measured(single,context.currentTime+.3);tone(higher,880);await engine.setPitch(d,{keylock:true,semitones:0});const restored=await measured(single,context.currentTime+.3);tone(restored,440);assert(engine.voices.get(0).liveKeylock===adapter&&adapter.snapshot().groups[0].id===id,'Rate/pitch replaced active live node');Object.assign(e,{rate,higher,restored,nodeReused:true});});
  await check('Production near/far seeks use original-time clock and bounded live windows',async e=>{await engine.seek(d,8.5);const near=await measured(single,d.anchorTime+.25);tone(near,550);await engine.seek(d,24);const far=await measured(single,d.anchorTime+.25);tone(far,880);Object.assign(e,{near,far,position:engine.position(d),snapshot:engine.voices.get(0).liveKeylock.snapshot()});});
  await check('Whole-deck raw scratch release restores live keylock through scheduled engine handoff',async e=>{await engine.beginDeckScratch(d,'engine-live-release');await engine.updateDeckScratch(d,{position:24,velocity:0},'engine-live-release');const held=await measured(single,context.currentTime+.03,.08);assert(held.peak===0,'Raw hold was not silent');const beforeRelease=context.currentTime;await engine.endDeckScratch(d,'engine-live-release');assert(engine.voices.get(0)?.liveKeylock,'Scratch release did not restore live voice');const when=d.anchorTime,transition=await measured(single,when-.08,.35),restored=await measured(single,when+.25);tone(restored,880);assert(transition.maxBelow005RunMs<=20,'Scratch release exceeds explicit20ms gap budget');Object.assign(e,{held,beforeRelease,when,transition,restored,snapshot:engine.voices.get(0).liveKeylock.snapshot()});});
